# Lazy Loading & Virtual Scrolling Components - Week 8 Performance
# Monitor Legislativo v4 - Efficient UI for 134k+ Documents
# ===============================================================
# Advanced UI components with lazy loading and virtual scrolling
# optimized for Brazilian legislative document browsing on Railway

library(shiny)
library(DT)
# shinydashboard loaded via R/000_load_shinydashboard.R preload file
library(htmlwidgets)\n\n# Global lazy loading configuration\n.LAZY_LOADING_CONFIG <- list(\n  # Virtual scrolling settings\n  virtual_scroll_enabled = TRUE,\n  page_size = 50,                    # Documents per page\n  buffer_size = 25,                  # Pre-load buffer\n  max_visible_rows = 100,            # Maximum rows in DOM\n  \n  # Lazy loading thresholds\n  lazy_load_threshold_px = 200,      # Pixels before loading\n  image_lazy_load_enabled = TRUE,\n  content_preview_chars = 200,       # Characters in preview\n  \n  # Performance optimization\n  debounce_scroll_ms = 100,          # Scroll event debouncing\n  render_throttle_ms = 50,           # Render throttling\n  memory_cleanup_interval = 30000,   # Memory cleanup (30s)\n  \n  # Brazilian legislative specific\n  priority_document_types = c(\"lei\", \"decreto\", \"portaria\"),\n  geographic_priority_states = c(\"SP\", \"RJ\", \"MG\", \"RS\", \"PR\"),\n  content_truncation_enabled = TRUE\n)\n\n# Global state management for lazy loading\n.LAZY_LOADING_STATE <- list(\n  current_page = 1,\n  total_documents = 0,\n  loaded_documents = list(),\n  visible_range = list(start = 1, end = 50),\n  loading_status = \"idle\",\n  performance_metrics = list()\n)\n\n#' Create Virtual Scrolling Data Table\n#' \n#' Creates a high-performance data table with virtual scrolling\n#' optimized for Brazilian legislative document browsing.\n#' \n#' @param output_id Character. Shiny output ID\n#' @param column_definitions List. Column configuration\n#' @param enable_search Logical. Enable built-in search\n#' @param enable_filters Logical. Enable column filters\n#' @return DT datatable with virtual scrolling\n#' @export\ncreate_virtual_datatable <- function(output_id, \n                                    column_definitions = NULL,\n                                    enable_search = TRUE,\n                                    enable_filters = TRUE) {\n  \n  cat(\"📊 Creating virtual scrolling data table:\", output_id, \"\\n\")\n  \n  # Default column definitions for legislative documents\n  if (is.null(column_definitions)) {\n    column_definitions <- get_default_legislative_columns()\n  }\n  \n  # Configure DT options for virtual scrolling\n  dt_options <- list(\n    # Virtual scrolling configuration\n    scrollY = \"400px\",\n    scrollCollapse = TRUE,\n    scroller = list(\n      displayBuffer = .LAZY_LOADING_CONFIG$buffer_size,\n      serverSide = TRUE,\n      deferRender = TRUE\n    ),\n    \n    # Performance optimizations\n    processing = TRUE,\n    serverSide = TRUE,\n    pageLength = .LAZY_LOADING_CONFIG$page_size,\n    lengthMenu = list(c(25, 50, 100, 200), c(\"25\", \"50\", \"100\", \"200\")),\n    \n    # Search and filter configuration\n    searching = enable_search,\n    searchDelay = 300,  # Debounce search\n    \n    # Column configuration\n    columnDefs = list(\n      list(\n        targets = \"_all\",\n        render = DT::JS(\"\n          function(data, type, row, meta) {\n            if (type === 'display' && data && data.length > 200) {\n              return '<span title=\"' + data + '\">' + data.substr(0, 200) + '...</span>';\n            }\n            return data;\n          }\n        \")\n      )\n    ),\n    \n    # Brazilian Portuguese localization\n    language = list(\n      url = \"//cdn.datatables.net/plug-ins/1.10.24/i18n/Portuguese-Brasil.json\"\n    ),\n    \n    # Additional performance settings\n    deferRender = TRUE,\n    stateSave = TRUE,\n    stateDuration = 300  # 5 minutes\n  )\n  \n  # Add column filters if enabled\n  if (enable_filters) {\n    dt_options$initComplete <- DT::JS(\"\n      function(settings, json) {\n        this.api().columns().every(function() {\n          var column = this;\n          var select = $('<select><option value=\"\"></option></select>')\n            .appendTo($(column.footer()).empty())\n            .on('change', function() {\n              var val = $.fn.dataTable.util.escapeRegex(\n                $(this).val()\n              );\n              column.search(val ? '^' + val + '$' : '', true, false).draw();\n            });\n          \n          column.data().unique().sort().each(function(d, j) {\n            if (d) {\n              select.append('<option value=\"' + d + '\">' + d + '</option>');\n            }\n          });\n        });\n      }\n    \")\n  }\n  \n  return(list(\n    options = dt_options,\n    column_definitions = column_definitions,\n    output_id = output_id\n  ))\n}\n\n#' Create Lazy Loading Document Cards\n#' \n#' Creates a lazy-loading card interface for document browsing\n#' with virtual scrolling and progressive loading.\n#' \n#' @param container_id Character. Container element ID\n#' @param card_template Function. Card rendering template\n#' @param load_batch_size Numeric. Documents to load per batch\n#' @return HTML container with lazy loading cards\n#' @export\ncreate_lazy_document_cards <- function(container_id,\n                                      card_template = NULL,\n                                      load_batch_size = 20) {\n  \n  cat(\"🃏 Creating lazy loading document cards:\", container_id, \"\\n\")\n  \n  # Default card template for legislative documents\n  if (is.null(card_template)) {\n    card_template <- create_default_document_card_template()\n  }\n  \n  # Create container with lazy loading infrastructure\n  lazy_container <- div(\n    id = container_id,\n    class = \"lazy-loading-container\",\n    \n    # Loading indicator\n    div(\n      id = paste0(container_id, \"_loading\"),\n      class = \"loading-indicator hidden\",\n      style = \"text-align: center; padding: 20px;\",\n      \n      tags$i(class = \"fa fa-spinner fa-spin\", style = \"font-size: 24px;\"),\n      br(),\n      \"Carregando documentos legislativos...\"\n    ),\n    \n    # Document cards container\n    div(\n      id = paste0(container_id, \"_cards\"),\n      class = \"document-cards-container\",\n      style = \"min-height: 400px;\"\n    ),\n    \n    # Load more trigger (invisible, for intersection observer)\n    div(\n      id = paste0(container_id, \"_trigger\"),\n      class = \"load-more-trigger\",\n      style = \"height: 1px; margin-bottom: 50px;\"\n    ),\n    \n    # Lazy loading JavaScript\n    tags$script(create_lazy_loading_javascript(container_id, load_batch_size))\n  )\n  \n  return(lazy_container)\n}\n\n#' Create Progressive Search Interface\n#' \n#' Creates a search interface with progressive loading and\n#' Brazilian legislative document specific features.\n#' \n#' @param search_id Character. Search input ID\n#' @param results_container_id Character. Results container ID\n#' @param enable_auto_complete Logical. Enable search suggestions\n#' @return HTML search interface\n#' @export\ncreate_progressive_search <- function(search_id,\n                                     results_container_id,\n                                     enable_auto_complete = TRUE) {\n  \n  cat(\"🔍 Creating progressive search interface:\", search_id, \"\\n\")\n  \n  # Search input with Brazilian legislative features\n  search_interface <- div(\n    class = \"progressive-search-container\",\n    \n    # Main search input\n    div(\n      class = \"form-group\",\n      \n      textInput(\n        inputId = search_id,\n        label = \"Buscar documentos legislativos\",\n        placeholder = \"Digite termos como 'lei', 'decreto', 'saúde', 'São Paulo'...\",\n        width = \"100%\"\n      ),\n      \n      # Search suggestions (auto-complete)\n      conditionalPanel(\n        condition = sprintf(\"input.%s.length > 2\", search_id),\n        div(\n          id = paste0(search_id, \"_suggestions\"),\n          class = \"search-suggestions hidden\",\n          style = \"position: absolute; z-index: 1000; background: white; border: 1px solid #ddd; max-height: 200px; overflow-y: auto;\"\n        )\n      )\n    ),\n    \n    # Advanced search filters\n    div(\n      class = \"advanced-search-filters\",\n      \n      fluidRow(\n        column(3,\n          selectInput(\n            inputId = paste0(search_id, \"_state\"),\n            label = \"Estado\",\n            choices = c(\"Todos\" = \"\", \n                       \"São Paulo\" = \"SP\", \"Rio de Janeiro\" = \"RJ\", \n                       \"Minas Gerais\" = \"MG\", \"Rio Grande do Sul\" = \"RS\",\n                       \"Paraná\" = \"PR\", \"Santa Catarina\" = \"SC\",\n                       \"Bahia\" = \"BA\", \"Distrito Federal\" = \"DF\"),\n            selected = \"\"\n          )\n        ),\n        \n        column(3,\n          selectInput(\n            inputId = paste0(search_id, \"_type\"),\n            label = \"Tipo de Documento\",\n            choices = c(\"Todos\" = \"\",\n                       \"Lei\" = \"lei\", \"Decreto\" = \"decreto\",\n                       \"Portaria\" = \"portaria\", \"Instrução Normativa\" = \"instrucao_normativa\"),\n            selected = \"\"\n          )\n        ),\n        \n        column(3,\n          dateInput(\n            inputId = paste0(search_id, \"_date_from\"),\n            label = \"Data Inicial\",\n            value = NULL,\n            language = \"pt-BR\"\n          )\n        ),\n        \n        column(3,\n          dateInput(\n            inputId = paste0(search_id, \"_date_to\"),\n            label = \"Data Final\",\n            value = NULL,\n            language = \"pt-BR\"\n          )\n        )\n      )\n    ),\n    \n    # Search results with progressive loading\n    div(\n      id = results_container_id,\n      class = \"search-results-container\",\n      \n      # Search status\n      div(\n        id = paste0(results_container_id, \"_status\"),\n        class = \"search-status\",\n        style = \"padding: 10px; background: #f8f9fa; border-radius: 4px; margin-bottom: 10px; display: none;\"\n      ),\n      \n      # Results container\n      div(\n        id = paste0(results_container_id, \"_results\"),\n        class = \"search-results\"\n      )\n    ),\n    \n    # Progressive search JavaScript\n    tags$script(create_progressive_search_javascript(search_id, results_container_id))\n  )\n  \n  return(search_interface)\n}\n\n#' Create Infinite Scroll Timeline\n#' \n#' Creates an infinite scrolling timeline for chronological\n#' document browsing with Brazilian legislative context.\n#' \n#' @param timeline_id Character. Timeline container ID\n#' @param group_by Character. Grouping method (\"date\", \"state\", \"type\")\n#' @return HTML timeline with infinite scroll\n#' @export\ncreate_infinite_scroll_timeline <- function(timeline_id, group_by = \"date\") {\n  \n  cat(\"📅 Creating infinite scroll timeline:\", timeline_id, \"\\n\")\n  \n  timeline_container <- div(\n    id = timeline_id,\n    class = \"infinite-scroll-timeline\",\n    \n    # Timeline header\n    div(\n      class = \"timeline-header\",\n      style = \"padding: 15px; background: #e3f2fd; border-radius: 4px; margin-bottom: 20px;\",\n      \n      h4(\"Linha do Tempo - Documentos Legislativos\"),\n      \n      # Timeline controls\n      fluidRow(\n        column(6,\n          selectInput(\n            inputId = paste0(timeline_id, \"_grouping\"),\n            label = \"Agrupar por\",\n            choices = c(\n              \"Data de Publicação\" = \"date\",\n              \"Estado\" = \"state\",\n              \"Tipo de Documento\" = \"type\",\n              \"Órgão Emissor\" = \"authority\"\n            ),\n            selected = group_by\n          )\n        ),\n        \n        column(6,\n          selectInput(\n            inputId = paste0(timeline_id, \"_sort\"),\n            label = \"Ordenação\",\n            choices = c(\n              \"Mais Recentes\" = \"desc\",\n              \"Mais Antigos\" = \"asc\",\n              \"Relevância\" = \"relevance\"\n            ),\n            selected = \"desc\"\n          )\n        )\n      )\n    ),\n    \n    # Timeline content\n    div(\n      id = paste0(timeline_id, \"_content\"),\n      class = \"timeline-content\",\n      style = \"position: relative;\"\n    ),\n    \n    # Loading indicator for timeline\n    div(\n      id = paste0(timeline_id, \"_loading\"),\n      class = \"timeline-loading hidden\",\n      style = \"text-align: center; padding: 30px;\",\n      \n      div(\n        class = \"spinner-border text-primary\",\n        role = \"status\",\n        span(class = \"sr-only\", \"Carregando...\")\n      ),\n      br(),\n      \"Carregando mais documentos...\"\n    ),\n    \n    # Infinite scroll JavaScript\n    tags$script(create_infinite_scroll_javascript(timeline_id))\n  )\n  \n  return(timeline_container)\n}\n\n#' Create Memory-Efficient Table Component\n#' \n#' Creates a table component optimized for large datasets\n#' with memory management and Brazilian legislative features.\n#' \n#' @param table_id Character. Table container ID\n#' @param max_memory_mb Numeric. Maximum memory usage in MB\n#' @return HTML table with memory management\n#' @export\ncreate_memory_efficient_table <- function(table_id, max_memory_mb = 100) {\n  \n  cat(\"📋 Creating memory-efficient table:\", table_id, \"\\n\")\n  \n  # Calculate optimal row limits based on memory\n  estimated_row_size_kb <- 2  # Estimated size per row\n  max_rows_in_memory <- (max_memory_mb * 1024) / estimated_row_size_kb\n  \n  table_container <- div(\n    id = table_id,\n    class = \"memory-efficient-table\",\n    \n    # Table controls\n    div(\n      class = \"table-controls\",\n      style = \"margin-bottom: 15px;\",\n      \n      fluidRow(\n        column(4,\n          numericInput(\n            inputId = paste0(table_id, \"_page_size\"),\n            label = \"Registros por página\",\n            value = .LAZY_LOADING_CONFIG$page_size,\n            min = 10,\n            max = min(500, max_rows_in_memory),\n            step = 10\n          )\n        ),\n        \n        column(4,\n          div(\n            class = \"memory-usage-indicator\",\n            style = \"padding: 8px;\",\n            \n            strong(\"Uso de Memória: \"),\n            span(\n              id = paste0(table_id, \"_memory_usage\"),\n              class = \"memory-usage-value\",\n              \"0 MB\"\n            ),\n            \"/\",\n            span(class = \"memory-limit\", paste0(max_memory_mb, \" MB\"))\n          )\n        ),\n        \n        column(4,\n          div(\n            class = \"performance-metrics\",\n            style = \"padding: 8px; font-size: 12px;\",\n            \n            div(\"Linhas carregadas: \", span(id = paste0(table_id, \"_rows_loaded\"), \"0\")),\n            div(\"Tempo de resposta: \", span(id = paste0(table_id, \"_response_time\"), \"0ms\"))\n          )\n        )\n      )\n    ),\n    \n    # Table container with virtual scrolling\n    div(\n      id = paste0(table_id, \"_container\"),\n      class = \"table-data-container\",\n      style = \"overflow-y: auto; max-height: 600px; border: 1px solid #dee2e6;\",\n      \n      # Placeholder for table content\n      div(\n        id = paste0(table_id, \"_placeholder\"),\n        class = \"table-placeholder\",\n        style = \"padding: 50px; text-align: center; color: #6c757d;\",\n        \n        tags$i(class = \"fas fa-table\", style = \"font-size: 48px; margin-bottom: 15px;\"),\n        br(),\n        \"Carregue dados para visualizar a tabela\"\n      )\n    ),\n    \n    # Memory management JavaScript\n    tags$script(create_memory_management_javascript(table_id, max_memory_mb))\n  )\n  \n  return(table_container)\n}\n\n# Helper functions for creating JavaScript components\n\n#' Create lazy loading JavaScript\ncreate_lazy_loading_javascript <- function(container_id, batch_size) {\n  \n  sprintf(\"\n    (function() {\n      const container = document.getElementById('%s');\n      const trigger = document.getElementById('%s_trigger');\n      const loading = document.getElementById('%s_loading');\n      \n      let isLoading = false;\n      let hasMoreData = true;\n      let currentBatch = 0;\n      \n      // Intersection Observer for lazy loading\n      const observer = new IntersectionObserver((entries) => {\n        entries.forEach(entry => {\n          if (entry.isIntersecting && !isLoading && hasMoreData) {\n            loadMoreDocuments();\n          }\n        });\n      }, {\n        rootMargin: '%dpx'\n      });\n      \n      if (trigger) {\n        observer.observe(trigger);\n      }\n      \n      function loadMoreDocuments() {\n        if (isLoading) return;\n        \n        isLoading = true;\n        loading.classList.remove('hidden');\n        \n        // Simulate API call - replace with actual Shiny communication\n        setTimeout(() => {\n          // This would be replaced with actual Shiny reactive updates\n          console.log('Loading batch', currentBatch, 'with', %d, 'documents');\n          \n          currentBatch++;\n          isLoading = false;\n          loading.classList.add('hidden');\n          \n          // Stop loading after 10 batches (demo)\n          if (currentBatch >= 10) {\n            hasMoreData = false;\n            observer.disconnect();\n          }\n        }, 1000);\n      }\n      \n      // Memory cleanup interval\n      setInterval(() => {\n        const cards = container.querySelectorAll('.document-card');\n        if (cards.length > %d) {\n          // Remove cards that are far off-screen\n          for (let i = 0; i < cards.length - %d; i++) {\n            const rect = cards[i].getBoundingClientRect();\n            if (rect.bottom < -500) {\n              cards[i].remove();\n            }\n          }\n        }\n      }, %d);\n    })();\n  \", \n  container_id, container_id, container_id,\n  .LAZY_LOADING_CONFIG$lazy_load_threshold_px,\n  batch_size,\n  .LAZY_LOADING_CONFIG$max_visible_rows,\n  .LAZY_LOADING_CONFIG$max_visible_rows,\n  .LAZY_LOADING_CONFIG$memory_cleanup_interval)\n}\n\n#' Create progressive search JavaScript\ncreate_progressive_search_javascript <- function(search_id, results_container_id) {\n  \n  sprintf(\"\n    (function() {\n      const searchInput = document.getElementById('%s');\n      const resultsContainer = document.getElementById('%s');\n      const statusDiv = document.getElementById('%s_status');\n      \n      let searchTimeout;\n      let currentPage = 1;\n      let isSearching = false;\n      \n      // Debounced search function\n      function debouncedSearch() {\n        clearTimeout(searchTimeout);\n        searchTimeout = setTimeout(() => {\n          performSearch();\n        }, %d);\n      }\n      \n      function performSearch() {\n        const query = searchInput.value.trim();\n        \n        if (query.length < 2) {\n          resultsContainer.innerHTML = '';\n          statusDiv.style.display = 'none';\n          return;\n        }\n        \n        if (isSearching) return;\n        \n        isSearching = true;\n        statusDiv.innerHTML = 'Buscando documentos legislativos...';\n        statusDiv.style.display = 'block';\n        \n        // This would integrate with Shiny reactive system\n        // For now, we'll show a placeholder\n        setTimeout(() => {\n          const resultCount = Math.floor(Math.random() * 1000) + 50;\n          statusDiv.innerHTML = `Encontrados ${resultCount} documentos para: \"${query}\"`;\n          \n          // Simulate progressive result loading\n          loadSearchResults(query, 1);\n          isSearching = false;\n        }, 500);\n      }\n      \n      function loadSearchResults(query, page) {\n        // This would be replaced with actual Shiny communication\n        console.log('Loading search results for:', query, 'page:', page);\n      }\n      \n      // Auto-complete functionality\n      function setupAutoComplete() {\n        const suggestions = [\n          'legislação', 'lei', 'decreto', 'portaria', 'instrução normativa',\n          'são paulo', 'rio de janeiro', 'minas gerais', 'bahia',\n          'saúde', 'educação', 'segurança', 'meio ambiente', 'transporte'\n        ];\n        \n        searchInput.addEventListener('input', (e) => {\n          const value = e.target.value.toLowerCase();\n          if (value.length > 1) {\n            const matches = suggestions.filter(s => s.includes(value));\n            showSuggestions(matches);\n          }\n          debouncedSearch();\n        });\n      }\n      \n      function showSuggestions(suggestions) {\n        const suggestionsDiv = document.getElementById('%s_suggestions');\n        if (suggestions.length > 0) {\n          suggestionsDiv.innerHTML = suggestions\n            .slice(0, 5)\n            .map(s => `<div class=\"suggestion-item\" style=\"padding: 8px; cursor: pointer; border-bottom: 1px solid #eee;\">${s}</div>`)\n            .join('');\n          suggestionsDiv.classList.remove('hidden');\n        } else {\n          suggestionsDiv.classList.add('hidden');\n        }\n      }\n      \n      setupAutoComplete();\n    })();\n  \", \n  search_id, results_container_id, results_container_id,\n  .LAZY_LOADING_CONFIG$debounce_scroll_ms * 3,  # Search debounce is longer\n  search_id)\n}\n\n#' Create infinite scroll JavaScript\ncreate_infinite_scroll_javascript <- function(timeline_id) {\n  \n  sprintf(\"\n    (function() {\n      const timelineContent = document.getElementById('%s_content');\n      const loadingIndicator = document.getElementById('%s_loading');\n      \n      let isLoading = false;\n      let hasMoreData = true;\n      let currentOffset = 0;\n      const batchSize = %d;\n      \n      // Throttled scroll handler\n      function throttledScrollHandler() {\n        if (isLoading || !hasMoreData) return;\n        \n        const scrollTop = timelineContent.scrollTop;\n        const scrollHeight = timelineContent.scrollHeight;\n        const clientHeight = timelineContent.clientHeight;\n        \n        // Load more when 200px from bottom\n        if (scrollTop + clientHeight >= scrollHeight - 200) {\n          loadMoreTimelineData();\n        }\n      }\n      \n      function loadMoreTimelineData() {\n        if (isLoading) return;\n        \n        isLoading = true;\n        loadingIndicator.classList.remove('hidden');\n        \n        // Simulate API call\n        setTimeout(() => {\n          console.log('Loading timeline batch at offset:', currentOffset);\n          \n          currentOffset += batchSize;\n          isLoading = false;\n          loadingIndicator.classList.add('hidden');\n          \n          // Demo: stop after 200 items\n          if (currentOffset >= 200) {\n            hasMoreData = false;\n          }\n        }, 800);\n      }\n      \n      // Add throttled scroll listener\n      let scrollTimeout;\n      timelineContent.addEventListener('scroll', () => {\n        clearTimeout(scrollTimeout);\n        scrollTimeout = setTimeout(throttledScrollHandler, %d);\n      });\n      \n      // Initial load\n      loadMoreTimelineData();\n    })();\n  \", \n  timeline_id, timeline_id,\n  .LAZY_LOADING_CONFIG$page_size,\n  .LAZY_LOADING_CONFIG$render_throttle_ms)\n}\n\n#' Create memory management JavaScript\ncreate_memory_management_javascript <- function(table_id, max_memory_mb) {\n  \n  sprintf(\"\n    (function() {\n      const tableContainer = document.getElementById('%s_container');\n      const memoryUsageSpan = document.getElementById('%s_memory_usage');\n      const rowsLoadedSpan = document.getElementById('%s_rows_loaded');\n      const responseTimeSpan = document.getElementById('%s_response_time');\n      \n      let currentMemoryUsage = 0;\n      let rowsLoaded = 0;\n      const maxMemoryMB = %d;\n      \n      function updateMemoryUsage() {\n        // Estimate memory usage based on DOM elements\n        const rows = tableContainer.querySelectorAll('tr');\n        const estimatedUsageMB = (rows.length * 2) / 1024; // Rough estimate\n        \n        currentMemoryUsage = Math.min(estimatedUsageMB, maxMemoryMB);\n        memoryUsageSpan.textContent = currentMemoryUsage.toFixed(1) + ' MB';\n        rowsLoadedSpan.textContent = rows.length;\n        \n        // Change color based on memory usage\n        const usagePercent = (currentMemoryUsage / maxMemoryMB) * 100;\n        if (usagePercent > 80) {\n          memoryUsageSpan.style.color = '#dc3545'; // Red\n        } else if (usagePercent > 60) {\n          memoryUsageSpan.style.color = '#ffc107'; // Yellow\n        } else {\n          memoryUsageSpan.style.color = '#28a745'; // Green\n        }\n        \n        // Trigger cleanup if memory usage is high\n        if (usagePercent > 90) {\n          performMemoryCleanup();\n        }\n      }\n      \n      function performMemoryCleanup() {\n        console.log('Performing memory cleanup for table:', '%s');\n        \n        // Remove off-screen rows to free memory\n        const rows = tableContainer.querySelectorAll('tr');\n        const containerRect = tableContainer.getBoundingClientRect();\n        \n        let removedCount = 0;\n        rows.forEach((row, index) => {\n          const rowRect = row.getBoundingClientRect();\n          // Remove rows that are far off-screen\n          if (rowRect.bottom < containerRect.top - 500 || \n              rowRect.top > containerRect.bottom + 500) {\n            if (index > 10 && index < rows.length - 10) { // Keep some buffer\n              row.remove();\n              removedCount++;\n            }\n          }\n        });\n        \n        if (removedCount > 0) {\n          console.log('Cleaned up', removedCount, 'off-screen rows');\n          updateMemoryUsage();\n        }\n      }\n      \n      // Update memory usage periodically\n      setInterval(updateMemoryUsage, 2000);\n      \n      // Initial update\n      updateMemoryUsage();\n    })();\n  \", \n  table_id, table_id, table_id, table_id,\n  max_memory_mb, table_id)\n}\n\n#' Get default column definitions for legislative documents\nget_default_legislative_columns <- function() {\n  \n  list(\n    list(\n      name = \"title\",\n      label = \"Título\",\n      width = \"300px\",\n      searchable = TRUE,\n      sortable = TRUE\n    ),\n    list(\n      name = \"document_type\",\n      label = \"Tipo\",\n      width = \"120px\",\n      searchable = TRUE,\n      sortable = TRUE\n    ),\n    list(\n      name = \"state\",\n      label = \"Estado\",\n      width = \"80px\",\n      searchable = TRUE,\n      sortable = TRUE\n    ),\n    list(\n      name = \"date_published\",\n      label = \"Data\",\n      width = \"120px\",\n      searchable = FALSE,\n      sortable = TRUE,\n      type = \"date\"\n    ),\n    list(\n      name = \"issuing_authority\",\n      label = \"Órgão\",\n      width = \"200px\",\n      searchable = TRUE,\n      sortable = TRUE\n    )\n  )\n}\n\n#' Create default document card template\ncreate_default_document_card_template <- function() {\n  \n  function(document) {\n    div(\n      class = \"document-card\",\n      style = \"border: 1px solid #dee2e6; border-radius: 8px; padding: 15px; margin-bottom: 15px; background: white;\",\n      \n      # Card header\n      div(\n        class = \"card-header\",\n        style = \"margin-bottom: 10px;\",\n        \n        h5(\n          class = \"card-title\",\n          style = \"margin: 0; color: #2c3e50;\",\n          document$title %||% \"Título não disponível\"\n        ),\n        \n        div(\n          class = \"card-meta\",\n          style = \"font-size: 12px; color: #6c757d; margin-top: 5px;\",\n          \n          span(class = \"badge badge-primary\", style = \"margin-right: 5px;\", \n               document$document_type %||% \"Tipo não especificado\"),\n          span(class = \"badge badge-secondary\", style = \"margin-right: 5px;\", \n               document$state %||% \"Estado não especificado\"),\n          span(class = \"text-muted\", \n               format(as.Date(document$date_published), \"%d/%m/%Y\") %||% \"Data não disponível\")\n        )\n      ),\n      \n      # Card content\n      div(\n        class = \"card-content\",\n        \n        p(\n          class = \"card-text\",\n          style = \"margin-bottom: 10px; line-height: 1.4;\",\n          substr(document$content %||% \"Conteúdo não disponível\", 1, \n                .LAZY_LOADING_CONFIG$content_preview_chars),\n          if (nchar(document$content %||% \"\") > .LAZY_LOADING_CONFIG$content_preview_chars) \"...\"\n        )\n      ),\n      \n      # Card footer\n      div(\n        class = \"card-footer\",\n        style = \"margin-top: 10px; padding-top: 10px; border-top: 1px solid #f8f9fa;\",\n        \n        div(\n          class = \"text-muted\",\n          style = \"font-size: 12px;\",\n          \n          strong(\"Órgão: \"), document$issuing_authority %||% \"Não especificado\", br(),\n          strong(\"Fonte: \"), document$source %||% \"Não especificada\"\n        ),\n        \n        div(\n          class = \"card-actions\",\n          style = \"margin-top: 8px;\",\n          \n          actionButton(\n            inputId = paste0(\"view_\", document$id),\n            label = \"Visualizar\",\n            class = \"btn btn-sm btn-outline-primary\",\n            style = \"margin-right: 5px;\"\n          ),\n          \n          actionButton(\n            inputId = paste0(\"export_\", document$id),\n            label = \"Exportar\",\n            class = \"btn btn-sm btn-outline-secondary\"\n          )\n        )\n      )\n    )\n  }\n}\n\n#' Update lazy loading state\n#' @param new_state List. New state values to update\n#' @export\nupdate_lazy_loading_state <- function(new_state) {\n  \n  for (key in names(new_state)) {\n    if (key %in% names(.LAZY_LOADING_STATE)) {\n      .LAZY_LOADING_STATE[[key]] <<- new_state[[key]]\n    }\n  }\n}\n\n#' Get current lazy loading performance metrics\n#' @return List with performance statistics\n#' @export\nget_lazy_loading_metrics <- function() {\n  \n  metrics <- list(\n    current_page = .LAZY_LOADING_STATE$current_page,\n    total_documents = .LAZY_LOADING_STATE$total_documents,\n    loaded_documents_count = length(.LAZY_LOADING_STATE$loaded_documents),\n    visible_range = .LAZY_LOADING_STATE$visible_range,\n    loading_status = .LAZY_LOADING_STATE$loading_status,\n    memory_efficiency = calculate_memory_efficiency(),\n    config = .LAZY_LOADING_CONFIG\n  )\n  \n  return(metrics)\n}\n\n#' Calculate memory efficiency based on loaded vs visible content\ncalculate_memory_efficiency <- function() {\n  \n  visible_range <- .LAZY_LOADING_STATE$visible_range\n  loaded_count <- length(.LAZY_LOADING_STATE$loaded_documents)\n  visible_count <- visible_range$end - visible_range$start + 1\n  \n  if (loaded_count == 0) return(100)\n  \n  efficiency <- (visible_count / loaded_count) * 100\n  return(min(100, max(0, efficiency)))\n}\n\ncat(\"🚀 Lazy Loading & Virtual Scrolling Components loaded - Week 8 Performance\\n\")\ncat(\"   Optimized for 134k+ Brazilian legislative documents on Railway\\n\")\n\n# Define the %||% operator if not already defined\nif (!exists(\"%||%\")) {\n  `%||%` <- function(x, y) if (isTRUE(is.null(x)) || isTRUE(length(x) == 0) || (is.character(x) && x == \"\")) y else x\n}"